fn xmlRegAtomPush(
    mut ctxt: xmlRegParserCtxtPtr,
    mut atom: xmlRegAtomPtr,
) -> c_int { unsafe {
    if atom.is_null() {
        (*ctxt).error = XML_REGEXP_COMPILE_ERROR as c_int;
        xmlRegexpErrCompile(
            ctxt,
            b"atom push: atom is NULL\0" as *const u8 as *const c_char,
        );
        return -(1 as c_int);
    }
    if (*ctxt).nbAtoms >= (*ctxt).maxAtoms {
        let mut newSize: size_t = (if (*ctxt).maxAtoms != 0 {
            (*ctxt).maxAtoms * 2 as c_int
        } else {
            4 as c_int
        }) as size_t;
        let mut tmp: *mut xmlRegAtomPtr = ::core::ptr::null_mut::<xmlRegAtomPtr>();
        tmp = xmlRealloc.expect("non-null function pointer")(
            (*ctxt).atoms as *mut c_void,
            newSize.wrapping_mul(::core::mem::size_of::<xmlRegAtomPtr>() as size_t),
        ) as *mut xmlRegAtomPtr;
        if tmp.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"allocating counter\0" as *const u8 as *const c_char,
            );
            return -(1 as c_int);
        }
        (*ctxt).atoms = tmp;
        (*ctxt).maxAtoms = newSize as c_int;
    }
    (*atom).no = (*ctxt).nbAtoms;
    let fresh8 = (*ctxt).nbAtoms;
    (*ctxt).nbAtoms = (*ctxt).nbAtoms + 1;
    let ref mut fresh9 = *(*ctxt).atoms.offset(fresh8 as isize);
    *fresh9 = atom;
    return 0 as c_int;
} }

